using System;using System.Data.Common;using System.IO;using System.Reflection;
class ApplyOrderLinkMigration{
 static int Main(string[]args){try{var a=Assembly.LoadFrom(Path.GetFullPath(args[0]));using(var c=(DbConnection)a.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){c.Open();
 foreach(var field in new[]{new[]{"OrderGroupId","BIGINT NULL"},new[]{"OrderGroupSequence","INT UNSIGNED NULL"},new[]{"OrderBaseNo","VARCHAR(64) NULL"}}){using(var q=c.CreateCommand()){q.CommandText="SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='OrderInfo' AND COLUMN_NAME='"+field[0]+"'";if(Convert.ToInt32(q.ExecuteScalar())==0){q.CommandText="ALTER TABLE OrderInfo ADD COLUMN "+field[0]+" "+field[1];q.ExecuteNonQuery();}}}
 using(var q=c.CreateCommand()){q.CommandText="SELECT CHARACTER_MAXIMUM_LENGTH FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='OrderInfo' AND COLUMN_NAME='OrderNo'";if(Convert.ToInt32(q.ExecuteScalar())<64){q.CommandText="ALTER TABLE OrderInfo MODIFY COLUMN OrderNo VARCHAR(64) NULL COMMENT '주문번호'";q.ExecuteNonQuery();}
 q.CommandText="SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='OrderInfo' AND INDEX_NAME='UX_OrderInfo_GroupSequence'";if(Convert.ToInt32(q.ExecuteScalar())==0){q.CommandText="ALTER TABLE OrderInfo ADD UNIQUE KEY UX_OrderInfo_GroupSequence (OrderGroupId,OrderGroupSequence)";q.ExecuteNonQuery();}
 q.CommandText="SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='OrderInfo' AND CONSTRAINT_NAME='FK_OrderInfo_GroupRoot'";if(Convert.ToInt32(q.ExecuteScalar())==0){q.CommandText="ALTER TABLE OrderInfo ADD CONSTRAINT FK_OrderInfo_GroupRoot FOREIGN KEY (OrderGroupId) REFERENCES OrderInfo(OrderId) ON DELETE RESTRICT";q.ExecuteNonQuery();}
 }Console.WriteLine("PASS: linked-order schema migration applied (existing orders retained)");}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
